import operator

OPERATIONS = {
    "plus": operator.add,
    "minus": operator.sub,
    "multiplied": operator.mul,
    "divided": operator.floordiv,
}


def _is_int(token):
    try:
        int(token)
        return True
    except ValueError:
        return False


def answer(question):
    if not question.startswith("What is") or not question.endswith("?"):
        raise ValueError("unknown operation")

    body = question[len("What is"):-1].strip()
    body = body.replace("multiplied by", "multiplied")
    body = body.replace("divided by", "divided")
    tokens = body.split()

    if not tokens:
        raise ValueError("syntax error")

    first = tokens[0]
    if _is_int(first):
        result = int(first)
    elif first in OPERATIONS:
        raise ValueError("syntax error")
    else:
        raise ValueError("unknown operation")

    tokens = tokens[1:]
    while tokens:
        op_token = tokens[0]
        if _is_int(op_token):
            raise ValueError("syntax error")
        if op_token not in OPERATIONS:
            raise ValueError("unknown operation")
        if len(tokens) < 2:
            raise ValueError("syntax error")

        num_token = tokens[1]
        if _is_int(num_token):
            num = int(num_token)
        elif num_token in OPERATIONS:
            raise ValueError("syntax error")
        else:
            raise ValueError("unknown operation")

        result = OPERATIONS[op_token](result, num)
        tokens = tokens[2:]

    return result
